    subprocess.run(["ffmpeg", "-nostdin", "-y", "-loglevel", "error", "-i", f, "-af", "equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000", "/tmp/tzbn_g009_0.wav"], check=True)
    du = float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", "/tmp/tzbn_g009_0.wav"]).decode())
